  // src/events/addSrcURLParam.js
  async function addSrcURLParam() {
    const currentUrl = new URL(window.location.href);
    const srcValue = currentUrl.searchParams.get("src");
    if (!srcValue)
      return;
    try {
      const response = await fetch(srcValue);
      const content2 = await response.text();
      loadCodeFromString(content2);
      removeQueryParam("src");
    } catch (error) {
      console.error("Error fetching content:", error);
    }
  }

  // src/events/addNumberScrubbing.ts
  init_preact_shim();
  function addNumberScrubbing() {
    const listen = createListener(document.body);
    const { view } = getStore();
    let dragging = false;
    let number2 = 0;
    let sigFigs = 0;
    let from = 0;
    let to = 0;
    listen("mousedown", "", (e3) => {
      const el = e3.target.closest("[data-number-scrubber]");
      if (el === null)
        return;
      dragging = true;
      from = Number(el.dataset.from);
      to = Number(el.dataset.to);
      const numStr = view.state.doc.sliceString(from, to).replaceAll(" ", "");
      number2 = Number(numStr);
      sigFigs = numStr.split(".")[1]?.length ?? 0;
    });
    listen("mousemove", "", (e3) => {
      if (dragging === false)
        return;
      if (e3.buttons === 0) {
        dragging = false;
        return;
      }
      e3.preventDefault();
      e3.stopPropagation();
      document.body.style.cursor = "ew-resize";
      number2 += sigFigs ? e3.movementX * 10 ** (-1 * sigFigs) : e3.movementX;
      const newValue = number2.toFixed(sigFigs);
      view.dispatch({
        changes: {
          from,
          to,
          insert: newValue
        }
      });
      to = from + newValue.length;
      runCode();
    });
    listen("mouseup", "", (e3) => {
      dragging = false;
      document.body.style.cursor = "default";
    });
  }

